style.css:
@-moz-document domain("roblox.com") {
/* Fondo global con tu imagen */
  html, body, #root, div[data-testid="app-container"] {
    background-image: url("https://i.imgur.com/W1fXR40.jpeg") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
  }

  /* Quita los fondos blancos y grises que tapan la imagen */
  .dark-theme, .light-theme, .theme-dark, .theme-light,
  .container, .content, .section, .rbx-body,
  .app-container, .app-content, .rbx-header, .rbx-footer,
  .profile-container, .game-page-container, .game-cards,
  #navigation, #container-main, #container-body, .page-content {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Asegura que el texto se vea encima del fondo */
  body, h1, h2, h3, p, span, a, .text {
    color: #fff !important;
  }
}
